//! `routes.lock`: every page's and endpoint's URL, and the redirects that
//! keep old URLs working (`docs/design/12-routing.md`, "`routes.lock` and
//! redirects"; `docs/compiler/codegen.md` §14).
//!
//! The lock is TOML, written by `k build` ([`implied`]) and committed:
//!
//! ```toml
//! # Generated by `k build`. Add a redirect, or delete the entry of a URL
//! # that no longer needs to work; nothing else is edited by hand.
//! # Format: docs/design/12-routing.md
//!
//! [pages.pricing]
//! declaration = "marketing.Pricing"
//! url = "/pricing"
//!
//! [endpoints.stripeWebhook]
//! declaration = "payments.StripeWebhook"
//! url = "/webhooks/stripe"
//!
//! [redirects]
//! "/plans" = "pricing"
//! ```
//!
//! `[pages.<case>]` and `[endpoints.<case>]` are keyed by the `Page` or
//! `Endpoint` case; `[redirects]` maps an old URL template to the case of
//! the page that answers it now, with a `308 Permanent Redirect`.
//!
//! **Renames.** A page without `at` takes its URL from its name, so
//! renaming it moves the URL. A recorded page is taken as **renamed** when
//! no page has its declaration or case any more and exactly one new page
//! of the same module (one the lock doesn't record) has the same path
//! parameters, and that page is the only such match: the old URL then gets
//! an automatic redirect to it, and redirects to the old case follow it.
//! Anything else whose URL is no longer served is a **removal**.
//!
//! **Writing** ([`implied`], `k build`): every current page and endpoint,
//! the recorded redirects (retargeted after renames, without those a page
//! now serves), an automatic redirect per detected rename, and the entries
//! of removed URLs, which stay until they are resolved by hand.
//!
//! **Checks** (`k check`, [`check`]): a recorded URL that no page or
//! endpoint serves any more, with no redirect and no detected rename, is
//! **K8007**, and so is a redirect to a page that no longer exists or
//! whose URL it can't build from the old one's parameters, and a detected
//! rename whose redirect isn't recorded yet (`k build` records it). A lock
//! that isn't TOML of this structure is **K8002**, and one in a format
//! newer than this toolchain's is **K8202** ([`k_sema::lockformat`]);
//! neither is checked further or rewritten. The lock is written in the
//! format it was read in. New pages need no
//! entry until the next build.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write;

use k_diagnostics::{Diagnostic, FileId, Span, TextRange, codes};
use k_sema::view::DeclId;
use k_syntax::SyntaxKind;
use serde::Deserialize;

use crate::cx::Gen;
use crate::lockfiles::{header_offset, line_at, project_file, range_of};

/// The header of a generated `routes.lock`.
const HEADER: &str = "# Generated by `k build`. Add a redirect, or delete the entry of a URL\n# that no longer needs to work; nothing else is edited by hand.\n# Format: docs/design/12-routing.md\n";

/// One page or endpoint as the lock records it.
#[derive(Clone, PartialEq, Eq, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Entry {
    /// The qualified name of the page, `marketing.Pricing`.
    pub(crate) declaration: String,
    /// Its URL template, `/product/{id}`.
    pub(crate) url: String,
}

/// The whole lock.
#[derive(Clone, PartialEq, Eq, Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct RoutesLock {
    /// `format = N` when the lock says it ([`k_sema::lockformat`], read
    /// before the rest); written by [`implied`], not by [`RoutesLock::to_toml`].
    #[serde(default)]
    pub(crate) format: Option<i64>,
    /// The view pages, by `Page` case.
    #[serde(default)]
    pub(crate) pages: BTreeMap<String, Entry>,
    /// The endpoint pages, by `Endpoint` case.
    #[serde(default)]
    pub(crate) endpoints: BTreeMap<String, Entry>,
    /// The redirects: old URL template to the `Page` case that answers it.
    #[serde(default)]
    pub(crate) redirects: BTreeMap<String, String>,
}

/// A TOML basic string.
fn quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if c.is_control() => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// A TOML key: bare when it can be.
fn key(s: &str) -> String {
    if !s.is_empty()
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    {
        s.to_owned()
    } else {
        quote(s)
    }
}

impl RoutesLock {
    /// Parses a lock.
    ///
    /// # Errors
    ///
    /// The parser's message and the byte range it points at.
    pub(crate) fn parse(
        text: &str,
    ) -> Result<RoutesLock, (String, Option<std::ops::Range<usize>>)> {
        toml::from_str(text).map_err(|e: toml::de::Error| (e.message().to_owned(), e.span()))
    }

    /// The canonical text: the header, pages, endpoints, then redirects,
    /// each sorted.
    pub(crate) fn to_toml(&self) -> String {
        let mut out = String::from(HEADER);
        for (section, entries) in [("pages", &self.pages), ("endpoints", &self.endpoints)] {
            for (case, e) in entries {
                let _ = write!(
                    out,
                    "\n[{section}.{}]\ndeclaration = {}\nurl = {}\n",
                    key(case),
                    quote(&e.declaration),
                    quote(&e.url)
                );
            }
        }
        if !self.redirects.is_empty() {
            out.push_str("\n[redirects]\n");
            for (from, to) in &self.redirects {
                let _ = writeln!(out, "{} = {}", quote(from), quote(to));
            }
        }
        out
    }
}

/// The path parameters of a URL template, in order: `{id}` and `{tab}` of
/// `/product/{id}/{tab}`.
fn path_params(template: &str) -> Vec<String> {
    template
        .split('{')
        .skip(1)
        .filter_map(|s| s.split_once('}').map(|(n, _)| n.to_owned()))
        .collect()
}

/// One page of the program, as the lock would record it.
#[derive(Clone, Debug)]
struct Current {
    /// The declaration.
    decl: DeclId,
    /// The `Page` or `Endpoint` case.
    case: String,
    /// The lock entry.
    entry: Entry,
    /// The module, `marketing`.
    module: Option<String>,
    /// Every `@Param` name.
    params: BTreeSet<String>,
}

/// The program's view pages and endpoint pages.
fn current(g: &Gen<'_>) -> (Vec<Current>, Vec<Current>) {
    let of = |d: DeclId| {
        let info = g.view.decl(d);
        Current {
            decl: d,
            case: crate::app::case_name(&info.name),
            entry: Entry {
                declaration: g.view.qualified_name(d),
                url: crate::app::template(g, d),
            },
            module: info.module.clone(),
            params: crate::app::params(g, d)
                .into_iter()
                .map(|(_, n, _, _)| n)
                .collect(),
        }
    };
    (
        crate::app::pages(g).into_iter().map(of).collect(),
        crate::app::endpoints(g).into_iter().map(of).collect(),
    )
}

/// `true` when page `d` names its URL with `at`.
fn is_named(g: &Gen<'_>, d: DeclId) -> bool {
    g.decl_node(d)
        .is_some_and(|n| n.children().any(|c| c.kind() == SyntaxKind::AtClause))
}

/// The recorded lock: `Ok(None)` without a `routes.lock`.
fn recorded<'a>(g: &'a Gen<'_>) -> Result<Option<(FileId, &'a str, RoutesLock)>, Box<Diagnostic>> {
    let Some((file, text)) = project_file(g, "routes.lock") else {
        return Ok(None);
    };
    if let Err(e) = k_sema::lockformat::read("routes.lock", text) {
        return Err(Box::new(e.diagnostic(file)));
    }
    match RoutesLock::parse(text) {
        Ok(lock) => Ok(Some((file, text, lock))),
        Err((message, span)) => Err(Box::new(Diagnostic::new(
            codes::INVALID_LOCKFILE,
            Span::new(
                file,
                span.map_or_else(|| TextRange::empty(0.into()), |s| range_of(text, s)),
            ),
            format!("routes.lock can't be read: {message}"),
        ))),
    }
}

/// What the recorded lock and the program say together.
struct Reconciled {
    /// The detected renames: (old case, recorded entry, new page).
    renames: Vec<(String, Entry, Current)>,
    /// The redirects: recorded ones (retargeted after renames, without
    /// those a page now serves) and one per detected rename.
    redirects: BTreeMap<String, String>,
}

/// Detects renames and computes the redirects the program implies.
fn reconcile(lock: &RoutesLock, pages: &[Current], endpoints: &[Current]) -> Reconciled {
    let recorded_decls: BTreeSet<&str> = lock
        .pages
        .values()
        .map(|e| e.declaration.as_str())
        .collect();
    let unrecorded: Vec<&Current> = pages
        .iter()
        .filter(|p| {
            !lock.pages.contains_key(&p.case)
                && !recorded_decls.contains(p.entry.declaration.as_str())
        })
        .collect();
    let gone: Vec<(&String, &Entry)> = lock
        .pages
        .iter()
        .filter(|(case, e)| {
            !pages
                .iter()
                .any(|p| &p.case == *case || p.entry.declaration == e.declaration)
        })
        .collect();
    let module_of = |declaration: &str| declaration.rsplit_once('.').map(|(m, _)| m.to_owned());
    let candidates = |e: &Entry| -> Vec<&Current> {
        unrecorded
            .iter()
            .copied()
            .filter(|p| {
                p.module == module_of(&e.declaration)
                    && path_params(&p.entry.url) == path_params(&e.url)
            })
            .collect()
    };
    let mut renames = Vec::new();
    for (case, e) in &gone {
        let mine = candidates(e);
        let [only] = mine.as_slice() else {
            continue;
        };
        // The new page must match this one entry alone.
        let rivals = gone
            .iter()
            .filter(|(_, other)| candidates(other).iter().any(|p| p.decl == only.decl))
            .count();
        if rivals == 1 {
            renames.push(((*case).clone(), (*e).clone(), (*only).clone()));
        }
    }
    let serves = |url: &str| pages.iter().chain(endpoints).any(|p| p.entry.url == url);
    let mut redirects = BTreeMap::new();
    for (from, to) in &lock.redirects {
        if serves(from) {
            continue;
        }
        let to = renames
            .iter()
            .find(|(old, _, _)| old == to)
            .map_or_else(|| to.clone(), |(_, _, p)| p.case.clone());
        redirects.insert(from.clone(), to);
    }
    for (_, e, p) in &renames {
        if !serves(&e.url) && e.url != p.entry.url {
            redirects.insert(e.url.clone(), p.case.clone());
        }
    }
    Reconciled { renames, redirects }
}

/// The redirects the server answers: those of `routes.lock` and the
/// automatic one of each page renamed since it was written, as (old URL
/// template, `Page` case). An unreadable lock has none.
pub(crate) fn redirects(g: &Gen<'_>) -> Vec<(String, String)> {
    let Ok(Some((_, _, lock))) = recorded(g) else {
        return Vec::new();
    };
    let (pages, endpoints) = current(g);
    reconcile(&lock, &pages, &endpoints)
        .redirects
        .into_iter()
        .collect()
}

/// The lock `k build` writes, when it differs from the recorded one (or
/// there is none and the app has a page). An unreadable lock is left for
/// `k check` to report.
pub(crate) fn implied(g: &Gen<'_>) -> Option<String> {
    let old = match recorded(g) {
        Err(_) => return None,
        Ok(r) => r.map(|(_, _, l)| l),
    };
    let (pages, endpoints) = current(g);
    if old.is_none() && pages.is_empty() && endpoints.is_empty() {
        return None;
    }
    let base = old.clone().unwrap_or_default();
    let reconciled = reconcile(&base, &pages, &endpoints);
    let mut new = RoutesLock {
        format: base.format,
        pages: pages
            .iter()
            .map(|p| (p.case.clone(), p.entry.clone()))
            .collect(),
        endpoints: endpoints
            .iter()
            .map(|p| (p.case.clone(), p.entry.clone()))
            .collect(),
        redirects: reconciled.redirects,
    };
    // A removal stays recorded, so `k check` keeps reporting it until a
    // redirect is added or the entry is deleted by hand.
    let served = |url: &str| {
        pages.iter().chain(&endpoints).any(|p| p.entry.url == url)
            || new.redirects.contains_key(url)
    };
    for (case, e) in &base.pages {
        let renamed = reconciled.renames.iter().any(|(old, _, _)| old == case);
        if !renamed && !served(&e.url) && !new.pages.contains_key(case) {
            new.pages.insert(case.clone(), e.clone());
        }
    }
    for (case, e) in &base.endpoints {
        if !served(&e.url) && !new.endpoints.contains_key(case) {
            new.endpoints.insert(case.clone(), e.clone());
        }
    }
    if old.as_ref() == Some(&new) {
        return None;
    }
    // Written in the format it was read in (`recorded` refused one it
    // can't read).
    let format = match recorded(g) {
        Ok(Some((_, text, _))) => k_sema::lockformat::read("routes.lock", text).unwrap_or_default(),
        _ => k_sema::lockformat::LockFormat::IMPLIED,
    };
    Some(format.stamp(&new.to_toml()))
}

/// The `routes.lock` checks (see the module documentation).
pub(crate) fn check(g: &Gen<'_>, out: &mut Vec<Diagnostic>) {
    let (file, text, lock) = match recorded(g) {
        Ok(Some(r)) => r,
        Ok(None) => return,
        Err(d) => {
            out.push(*d);
            return;
        }
    };
    let (pages, endpoints) = current(g);
    let reconciled = reconcile(&lock, &pages, &endpoints);
    let at_entry = |section: &str, case: &str| {
        Span::new(
            file,
            header_offset(text, section, case)
                .map_or_else(|| TextRange::empty(0.into()), |o| line_at(text, o)),
        )
    };
    let at_redirect = |from: &str| {
        let needle = quote(from);
        Span::new(
            file,
            text.find(&needle).map_or_else(
                || TextRange::empty(0.into()),
                |o| {
                    let start = text[..o].rfind('\n').map_or(0, |n| n + 1);
                    line_at(text, start)
                },
            ),
        )
    };
    let serves = |url: &str| pages.iter().chain(&endpoints).any(|p| p.entry.url == url);
    let decl_span = |d: DeclId| {
        let info = g.view.decl(d);
        Span::new(info.file, info.name_range)
    };
    for (case, e) in &lock.pages {
        if serves(&e.url) || lock.redirects.contains_key(&e.url) {
            continue;
        }
        if let Some((_, _, p)) = reconciled.renames.iter().find(|(old, _, _)| old == case) {
            out.push(
                Diagnostic::new(
                    codes::REMOVED_URL,
                    decl_span(p.decl),
                    format!(
                        "`{}` was renamed from `{}`, so its URL moved from `{}` to `{}`, but routes.lock doesn't record the redirect from the old URL yet",
                        p.entry.declaration, e.declaration, e.url, p.entry.url
                    ),
                )
                .with_label(at_entry("pages", case), "recorded here")
                .with_help("run `k build`, which records the redirect, and commit routes.lock"),
            );
            continue;
        }
        let same = pages
            .iter()
            .find(|p| p.entry.declaration == e.declaration || &p.case == case);
        let mut d = match same {
            Some(p) => Diagnostic::new(
                codes::REMOVED_URL,
                decl_span(p.decl),
                format!(
                    "the URL of `{}` changed from `{}` to `{}`, and nothing serves the old one",
                    p.entry.declaration, e.url, p.entry.url
                ),
            )
            .with_label(at_entry("pages", case), "recorded here"),
            None => Diagnostic::new(
                codes::REMOVED_URL,
                at_entry("pages", case),
                format!(
                    "`{}` (page `{}`) is no longer served: `{}` was removed or renamed",
                    e.url, case, e.declaration
                ),
            ),
        };
        if same.is_some_and(|p| !is_named(g, p.decl)) {
            d = d.with_note(
                "a page without `at` takes its URL from its name and its required parameters",
            );
        }
        out.push(d.with_help(format!(
            "keep the URL with `at \"{}\"`, add a redirect under `[redirects]` in routes.lock (`{} = \"<page case>\"`), or delete the entry once no link to it needs to work",
            e.url,
            quote(&e.url)
        )));
    }
    for (case, e) in &lock.endpoints {
        if serves(&e.url) {
            continue;
        }
        out.push(
            Diagnostic::new(
                codes::REMOVED_URL,
                at_entry("endpoints", case),
                format!(
                    "`{}` (endpoint `{}`) is no longer served, and something outside the app calls it",
                    e.url, case
                ),
            )
            .with_help(format!(
                "keep the endpoint's `at \"{}\"`, or delete the entry from routes.lock once no external system calls it",
                e.url
            )),
        );
    }
    for (from, to) in &lock.redirects {
        if serves(from) {
            continue;
        }
        let target = reconciled
            .redirects
            .get(from)
            .and_then(|case| pages.iter().find(|p| &p.case == case));
        let Some(target) = target else {
            out.push(
                Diagnostic::new(
                    codes::REMOVED_URL,
                    at_redirect(from),
                    format!("the redirect from `{from}` goes to `{to}`, which is no longer a page"),
                )
                .with_help("point it at the page that answers the URL now, or delete it once no link to it needs to work"),
            );
            continue;
        };
        let from_params: BTreeSet<String> = path_params(from).into_iter().collect();
        let needed: BTreeSet<String> = path_params(&target.entry.url).into_iter().collect();
        let unknown: Vec<&String> = from_params.difference(&target.params).collect();
        let missing: Vec<&String> = needed.difference(&from_params).collect();
        if !unknown.is_empty() || !missing.is_empty() {
            let mut d = Diagnostic::new(
                codes::REMOVED_URL,
                at_redirect(from),
                format!(
                    "the redirect from `{from}` can't build the URL of `{}` (`{}`)",
                    target.case, target.entry.url
                ),
            );
            for u in unknown {
                d = d.with_note(format!("`{{{u}}}` is not a parameter of `{}`", target.case));
            }
            for m in missing {
                d = d.with_note(format!(
                    "`{}` needs `{{{m}}}`, which the old URL doesn't have",
                    target.case
                ));
            }
            out.push(d.with_help("redirect to a page whose required parameters the old URL has"));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn written_locks_read_back() {
        let entry = |d: &str, u: &str| Entry {
            declaration: d.to_owned(),
            url: u.to_owned(),
        };
        let lock = RoutesLock {
            format: None,
            pages: [
                ("pricing".to_owned(), entry("site.Pricing", "/pricing")),
                ("odd\"case".to_owned(), entry("site.Odd", "/a\\b")),
            ]
            .into_iter()
            .collect(),
            endpoints: [("health".to_owned(), entry("site.Health", "/health"))]
                .into_iter()
                .collect(),
            redirects: [("/plans/{id}".to_owned(), "pricing".to_owned())]
                .into_iter()
                .collect(),
        };
        let text = lock.to_toml();
        assert!(text.starts_with(HEADER), "{text}");
        assert_eq!(RoutesLock::parse(&text).expect("reads"), lock);
    }

    #[test]
    fn bad_locks_are_rejected_with_a_place() {
        for text in [
            "page pricing \"/pricing\"\n",
            "[pages.a]\nurl = \"/a\"\n",
            "[pages.a]\ndeclaration = \"x.A\"\nurl = 3\n",
            "[redirects]\n\"/a\" = 1\n",
            "colour = \"red\"\n",
        ] {
            let (message, _) = RoutesLock::parse(text).expect_err(text);
            assert!(!message.is_empty(), "{text:?}");
        }
    }

    #[test]
    fn path_parameters_are_read_in_order() {
        assert_eq!(path_params("/product/{id}/{tab}"), ["id", "tab"]);
        assert!(path_params("/pricing").is_empty());
        assert_eq!(path_params("/a/{b"), Vec::<String>::new());
    }
}
